{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Reject the **20% / AUD 4.8m cap** and **18-month period**. Seek **25% / AUD 6m** and **24 months after Completion**."
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "Reject the proposed **AUD 25,000 de minimis** and **AUD 250,000 deductible basket**."
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Reject the **20% / AUD 4.8m cap** and **18-month period**. Seek **25% / AUD 6m** and **24 months after Completion**."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Reject folding capacity and title into the general regime."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Expressly carve **fraud, wilful concealment and deliberate misconduct** out of every cap, basket, time limit, exclusive-remedy and non-reliance provision"
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Delete deemed disclosure of the entire data room, accounts, registers and public records, and any “discoverable by a prudent search” test."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Delete the blanket bar for buyer or adviser knowledge."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Require **effective change-control consent and evidence that clause 11.3 conditions are satisfied before Completion**, as a condition precedent."
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Do not accept an ordinary post-Completion release; any exception needs an irrevocable undertaking **and Amelia’s approval**."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Require an express line item or seller-funded treatment, including any triggered payroll tax, superannuation and other on-costs once established."
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Seek verification and broaden the specific IP indemnity to cover ownership, use and transfer-related loss, while preserving the contractual SOW3 payment cure."
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Require preservation of logs, prompt investigation, cooperation and updates, with an appropriate pre-Completion covenant and targeted protection if findings warrant it."
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "The three renewals total **AUD 330,000**, but their ordinary-course status and whether they are accrued, unavoidable or terminable are not established."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Keep title, tax, IP, payment and covenant claims, and specific indemnities, in their appropriate separate regimes."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "Obtain independent evidence of ownership, authority and absence of encumbrances: DD-012 is a supplied internal register, not independent proof."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Do not treat tax or IP warranties as settled under the general cap."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": false
}

